interface LinkNode {
  tag: string;
  attrs: Record<string, string>;
  content: string;
}

export function parseRichTextString(richTextString: string): (string | LinkNode)[] {
  const tagRegex = /<(a|b)(\s+[^>]*)?>([^<]*)<\/\1>/g;
  const result = [];
  let lastIndex = 0;
  let match;

  const parseAttributes = (attrsString: string) => {
    const attrs: Record<string, string> = {};
    const attrRegex = /(\w+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
    let attrMatch;
    while ((attrMatch = attrRegex.exec(attrsString)) !== null) {
      const [, attrName, doubleQuotedValue, singleQuotedValue] = attrMatch;
      const attrValue = doubleQuotedValue !== undefined ? doubleQuotedValue : singleQuotedValue;
      if (attrName && attrValue !== undefined && !attrName.startsWith('on')) {
        attrs[attrName] = attrValue;
      }
    }
    return attrs;
  };

  while ((match = tagRegex.exec(richTextString)) !== null) {
    const [, tagName, attrsString = '', content = ''] = match;

    // 保留匹配之前的文本部分
    if (match.index > lastIndex) {
      result.push(richTextString.slice(lastIndex, match.index));
    }

    // 解析属性并构建属性对象
    const attrs = parseAttributes(attrsString);

    // 将解析后的对象加入结果数组
    if (tagName) {
      result.push({ tag: tagName, attrs, content });
    }

    // 更新最后处理的索引
    lastIndex = tagRegex.lastIndex;
  }

  // 保留最后一个匹配后的文本部分
  if (lastIndex < richTextString.length) {
    result.push(richTextString.slice(lastIndex));
  }

  return result;
}
