import { Component, Prop, h, Host, Element, State } from '@stencil/core';
import { KsTextVariant, ColorShortcut } from './types';
import { Slot, Slots } from '@src/framework/decorators';
import { Placement } from '@floating-ui/dom';
import { parseRichTextString } from '@src/components/ks-text/richTextParser';
import { asObject } from '@src/shared/type-utils';

function removeAllChildNodes(parentNode: HTMLElement) {
  while (parentNode.firstChild) {
    parentNode.removeChild(parentNode.firstChild);
  }
}

const TOOLTIP_DELAY = { open: 200 };

/**
 * @slot default - Default text content rendered by the component.
 * @slot definition - Slot for content to be displayed inside the definition hint tooltip.
 */
@Component({
  tag: 'ks-text',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsText {
  @Element() textContainerEl!: HTMLKsTextElement;

  /** To render text by passing a rich text string, it currently only supports parsing <a> and <b> tags in the text, such as `You can <a href="help.com">learn more</a>.` */
  @Prop() richTextString = '';
  /**
   * Typography variant for different text styles. Can be one of the following values:
   * `headlineLg`, `headlineMd`, `headlineSm`, `titleLg`, `titleMd`, `titleSm`,
   * `bodyLg`, `bodyMd`, `bodySm`, `labelLg`, `labelMd`, `labelSm`.
   */
  @Prop() variant?: KsTextVariant = 'bodyMd';
  /**
   * color of the text, which sets the color based on the provided color. Can be one of the following values:
   * `"inherit"`, `"primary"`, `"support"`, `"error"`, `"warning"`, `"success"`, `"info"`, `"neutral"`, `"neutralHigh"`, `"neutralLow"`.
   */
  @Prop() color?: ColorShortcut = 'inherit';
  /**
   * Determines if the text should be truncated with an ellipsis.
   * Can be either:
   * - A boolean: when `true`, the text is truncated with an ellipsis if it exceeds the container width.
   * - An object:
   *   - `tooltip`: when `true`, a tooltip will display the full text on hover.
   *   - `maxLines` (optional): the maximum number of lines before truncating the text.
   */
  @Prop() ellipsis: boolean | { tooltip: boolean | (() => string); maxLines?: number } = false;

  /** Set the `definition` prop will style the text as a definition term, and show a tooltip when hovered, with the content of `definition` prop. */
  @Prop() definition?: string;

  /** The props to override in popup. */
  @Prop() partProps?: { popup?: { inverse?: boolean; placement?: Placement } & Record<string, unknown> };

  @Slot({ rootname: 'textContainerEl', slotname: 'definition' }) private definitionSlots?: Slots;

  private defaultSlotEl?: HTMLSlotElement;

  private popoverContentEl?: HTMLElement;

  @State() hasOverflow = false;

  get enableEllipsisTooltip(): boolean {
    return this.ellipsis && asObject(this.ellipsis)?.tooltip !== false;
  }

  private tooltipEl?: HTMLKsTooltipElement;
  private _tooltipTimer?: ReturnType<typeof setTimeout>;
  private onPointerEnterTextContent = () => {
    if (!this.enableEllipsisTooltip) {
      return;
    }

    clearTimeout(this._tooltipTimer);

    const { scrollHeight, clientHeight, scrollWidth, clientWidth } = this.textContainerEl;
    this.hasOverflow = scrollHeight > clientHeight || scrollWidth > clientWidth;
    if (this.hasOverflow) {
      this._tooltipTimer = setTimeout(() => {
        if (this.tooltipEl) {
          this.updatePopoverContent();
          this.tooltipEl.open = true;
        }
      }, TOOLTIP_DELAY.open);
    }
  };
  private onPointerLeaveTextContent = () => {
    if (!this.enableEllipsisTooltip) {
      return;
    }

    clearTimeout(this._tooltipTimer);

    this._tooltipTimer = setTimeout(() => {
      if (this.tooltipEl) {
        this.tooltipEl.open = false;
      }
    }, TOOLTIP_DELAY.open);
  };

  private updatePopoverContent = (el = this.popoverContentEl) => {
    this.popoverContentEl = el;
    if (this.popoverContentEl) {
      removeAllChildNodes(this.popoverContentEl);
      const tooltipConfig = asObject(this.ellipsis)?.tooltip;
      if (typeof tooltipConfig === 'function') {
        this.popoverContentEl.textContent = tooltipConfig() || '';
      } else if (this.defaultSlotEl) {
        this.defaultSlotEl.assignedNodes().forEach((node) => this.popoverContentEl?.appendChild(node.cloneNode(true)));
      }
    }
  };

  private renderRichTextString() {
    return parseRichTextString(this.richTextString)
      .map((node) => {
        if (typeof node === 'object') {
          if (node.tag === 'a') {
            return (
              <ks-link {...node.attrs} target="_blank">
                {node.content}
              </ks-link>
            );
          } else if (node.tag === 'b') {
            return <b>{node.content}</b>;
          }
        }
        return node;
      })
      .filter(Boolean);
  }

  private renderText() {
    const text = (
      <slot ref={(el) => (this.defaultSlotEl = el as HTMLSlotElement)}>
        {this.richTextString && this.renderRichTextString()}
      </slot>
    );

    if (this.definition || this.definitionSlots) {
      return (
        <ks-tooltip>
          {text}
          <div class="tooltip-content" slot="content">
            <slot name="definition">{this.definition}</slot>
          </div>
        </ks-tooltip>
      );
    } else {
      return text;
    }
  }

  private getAnchorEl = () => this.textContainerEl;

  render() {
    const shouldRenderHoverTooltip =
      !this.definition &&
      !this.definitionSlots &&
      this.hasOverflow &&
      (this.ellipsis === true || (typeof this.ellipsis === 'object' && this.ellipsis.tooltip));
    const maxLines = typeof this.ellipsis === 'object' ? this.ellipsis.maxLines : false;
    return (
      <Host
        class="KsText"
        ks-variant={this.variant || 'bodyMd'}
        ks-color={this.color || 'inherit'}
        ks-ellipsis={this.ellipsis ? '' : undefined}
        ks-maxLines={maxLines ? true : undefined}
        ks-definition={Boolean(this.definition || this.definitionSlots)}
        style={maxLines ? { display: '-webkit-box', '-webkit-line-clamp': maxLines.toString() } : {}}
        onPointerenter={this.onPointerEnterTextContent}
        onPointerleave={this.onPointerLeaveTextContent}
      >
        {this.renderText()}
        {shouldRenderHoverTooltip && (
          <ks-tooltip
            ref={(el) => (this.tooltipEl = el)}
            size="auto"
            trigger="manual"
            {...(this.partProps?.popup || {})}
            delay={TOOLTIP_DELAY}
            anchorEl={this.getAnchorEl}
            style={{ ...(this.partProps?.popup?.['style'] || {}), visibility: this.hasOverflow ? undefined : 'hidden' }}
          >
            <div
              class="tooltip-content"
              style={{
                mixBlendMode: this.partProps?.popup?.inverse ? 'difference' : undefined,
              }}
              slot="content"
              ref={this.updatePopoverContent}
            ></div>
          </ks-tooltip>
        )}
      </Host>
    );
  }
}
